+        async fetchGithubAppSlug(input) {
+            const clientId = (
+                document.querySelector('[name=star_aid_github_app_client_id]')?.value || ''
+            ).trim();
+            if (!clientId) {
+                this.testResult = {
+                    success: false,
+                    message: '{{ _("system_config.github_app_slug_client_id_required") }}',
+                };
+                this.clearTestResult();
+                return;
+            }
+
+            this.fetchingGithubAppSlug = true;
+            this.testResult = null;
+            try {
+                const response = await fetch('/system-config/github-app-slug', {
+                    method: 'POST',
+                    headers: {
+                        'Content-Type': 'application/json',
+                        'X-CSRF-Token': this.csrfToken,
+                    },
+                    body: JSON.stringify({ clientId }),
+                });
+                const data = await response.json().catch(() => ({}));
+                if (!response.ok || !data.success) {
+                    this.testResult = data.message
+                        ? data
+                        : {
+                            success: false,
+                            message: '{{ _("system_config.github_app_slug_lookup_failed") }}',
+                        };
+                    return;
+                }
+
+                if (input && data.slug) {
+                    input.value = data.slug;
+                    input.dispatchEvent(new Event('input', { bubbles: true }));
+                }
+                this.testResult = data;
+            } catch (e) {
+                this.testResult = {
+                    success: false,
+                    message: '{{ _("system_config.test_failed") }}' + e.message,
+                };
+            } finally {
+                this.fetchingGithubAppSlug = false;
+                this.clearTestResult();
+            }
+        },
+
         clearTestResult() {
             setTimeout(() => { this.testResult = null; }, 5000);
         }
